-- North-up local map. Artwork/transforms are generated by tools/campus/build_minimap.py.
-- The shared HUD queries the reserved rectangle before placing cards and prompts.
local sEnabled = mod_storage_load("sgl_minimap_visible") ~= "0"
local sTextures = {}
local sTargets = {}
local sAreaKey = nil
local sChatUntil = 0
local HEADINGS = { "S", "SE", "E", "NE", "N", "NW", "W", "SW" }

local function texture(name)
    if sTextures[name] == nil then sTextures[name] = get_texture_info(name) or false end
    return sTextures[name] or nil
end

local function current_map()
    local np, m = gNetworkPlayers[0], gMarioStates[0]
    if np == nil or m == nil or m.area == nil then return nil end
    local best, lowest = nil, nil
    local floor = m.floorHeight or m.pos.y
    for _, map in ipairs(SGL_MINIMAP_MAPS or {}) do
        if map.level == np.currLevelNum and map.area == np.currAreaIndex then
            if map.height == nil then return map end
            if lowest == nil or map.height < lowest.height then lowest = map end
            if map.height <= floor + 80 and (best == nil or map.height > best.height) then best = map end
        end
    end
    return best or lowest
end

function sgl_minimap_rect()
    if not sEnabled or sgl_hud_blocked() or current_map() == nil then return nil end
    if djui_is_chatbox_open() or get_time() < sChatUntil then return nil end
    local m = gMarioStates[0]
    -- Preserve hide-and-seek's hidden positions and the counting blackout.
    local ctx = sgl_mission_ctx ~= nil and sgl_mission_ctx() or nil
    if ctx ~= nil and ctx.def.id == "libwest_hideseek" and ctx.s == SGL_MS_ACTIVE then return nil end
    if m.area.camera == nil or m.area.camera.cutscene ~= 0 then return nil end
    djui_hud_set_resolution(RESOLUTION_N64)
    return { x = 8, y = djui_hud_get_screen_height() - 93, w = 75, h = 85 }
end

-- Mission scripts already identify their active world waypoints via this helper.
-- Reuse them instead of duplicating each minigame's target-selection logic.
function sgl_minimap_track(pos, label, col)
    if label == nil or label == "" then return end
    local key = label .. ":" .. math.floor(pos.x / 50) .. ":" .. math.floor(pos.z / 50)
    sTargets[key] = { x = pos.x, y = pos.y, z = pos.z, color = col or SGL_HUD_GOLD, at = get_global_timer() }
end

local function update()
    local np = gNetworkPlayers[0]
    if np == nil then return end
    local key = np.currLevelNum .. ":" .. np.currAreaIndex .. ":" .. np.currActNum
    if key ~= sAreaKey then sTargets, sAreaKey = {}, key end
    local now = get_global_timer()
    for id, target in pairs(sTargets) do
        if now - target.at > 4 then sTargets[id] = nil end
    end
end

local function draw()
    local box = sgl_minimap_rect()
    if box == nil then return end
    local map, m, np = current_map(), gMarioStates[0], gNetworkPlayers[0]
    local art = texture(map.texture)
    if art == nil then return end
    local x, y, size = box.x + 5, box.y + 12, box.w - 10
    local span = math.min(map.span, map.height ~= nil and 11000 or 24000)
    local half = span / 2
    local centerX = math.max(map.minX + half, math.min(map.minX + map.span - half, m.pos.x))
    local centerZ = math.max(map.minZ + half, math.min(map.minZ + map.span - half, m.pos.z))
    -- Crop in texture coordinates: the engine's HUD scissor transform does
    -- not support these N64 screen coordinates correctly. Snap the projection
    -- to the same source pixels so landmarks and markers stay aligned.
    local tileW = math.max(1, math.min(art.width, math.floor(span / map.span * art.width + 0.5)))
    local tileH = math.max(1, math.min(art.height, math.floor(span / map.span * art.height + 0.5)))
    local tileX = math.max(0, math.min(art.width - tileW,
        math.floor((centerX - half - map.minX) / map.span * art.width)))
    local tileY = math.max(0, math.min(art.height - tileH,
        math.floor((centerZ - half - map.minZ) / map.span * art.height)))
    local left = map.minX + tileX / art.width * map.span
    local top = map.minZ + tileY / art.height * map.span
    local scale = size / (tileW / art.width * map.span)
    local scaleZ = size / (tileH / art.height * map.span)
    local function project(px, pz)
        return x + (px - left) * scale, y + (pz - top) * scaleZ
    end
    local function dot(px, pz, color, edge)
        local sx, sy = project(px, pz)
        if not edge and (sx < x + 2 or sx > x + size - 2 or sy < y + 2 or sy > y + size - 2) then return end
        sx, sy = math.max(x + 2, math.min(x + size - 2, sx)), math.max(y + 2, math.min(y + size - 2, sy))
        sgl_hud_rect(sx - 2, sy - 2, 4, 4, 5, 12, 21, 255)
        sgl_hud_rect(sx - 1, sy - 1, 2, 2, color[1], color[2], color[3], 255)
    end

    djui_hud_set_resolution(RESOLUTION_N64)
    djui_hud_set_font(FONT_ALIASED)
    sgl_hud_rect(box.x + 1, box.y + 2, box.w, box.h, 0, 0, 0, 90)
    sgl_hud_rect(box.x, box.y, box.w, box.h, 7, 17, 38, 235)
    sgl_hud_rect(box.x, box.y, box.w, 2, 238, 133, 52, 255)
    sgl_hud_text_fit(map.label, box.x + 5, box.y + 4, 0.20, box.w - 25, { 219, 231, 242 }, 1)
    -- Artwork stays north-up; the compass reports the player's heading.
    local heading = HEADINGS[math.floor((m.faceAngle.y % 0x10000 + 0x1000) / 0x2000) % 8 + 1]
    sgl_hud_text_center(heading, box.x + box.w - 10, box.y + 4, 0.20, SGL_HUD_GOLD, 1)
    sgl_hud_rect(x, y, size, size, 17, 29, 42, 255)
    djui_hud_set_filter(FILTER_LINEAR)
    djui_hud_set_color(255, 255, 255, 255)
    djui_hud_render_texture_tile(art, x, y, size / tileW, size / tileH, tileX, tileY, tileW, tileH)

    if np.currLevelNum == SGL_HUB_LEVEL then
        for _, door in ipairs(SGL_MINIMAP_DOORS or {}) do
            local stage = sgl_stage_by_door(door.door)
            if stage ~= nil and sgl_stage_ready(stage) then dot(door.x, door.z, { 240, 169, 82 }, false) end
        end
    end
    for i = 1, MAX_PLAYERS - 1 do
        local other, player = gNetworkPlayers[i], gMarioStates[i]
        if other ~= nil and other.connected and player ~= nil and other.currLevelNum == np.currLevelNum
            and other.currAreaIndex == np.currAreaIndex and other.currActNum == np.currActNum
            and (map.height == nil or math.abs((player.floorHeight or player.pos.y) - map.height) < 400) then
            dot(player.pos.x, player.pos.z, { 112, 221, 233 }, false)
        end
    end
    for _, target in pairs(sTargets) do
        if get_global_timer() - target.at <= 4 and (map.height == nil or math.abs(target.y - map.height) < 500) then
            dot(target.x, target.z, target.color, true)
        end
    end
    local px, py = project(m.pos.x, m.pos.z)
    -- A rotated 7px square needs 5px clearance to remain inside the map.
    px, py = math.max(x + 5, math.min(x + size - 5, px)), math.max(y + 5, math.min(y + size - 5, py))
    local arrow = texture("sgl_minimap_player")
    if arrow ~= nil then
        djui_hud_set_color(255, 255, 255, 255)
        djui_hud_set_rotation(m.faceAngle.y - 0x8000, 0.5, 0.5)
        djui_hud_render_texture(arrow, px - 3.5, py - 3.5, 7 / arrow.width, 7 / arrow.height)
        djui_hud_set_rotation(0, 0, 0)
    end
    local meters = map.height ~= nil and 20 or 50
    local bar = meters * 100 * scale
    sgl_hud_rect(x, y + size + 3, bar, 1, 185, 207, 225, 255)
    sgl_hud_text(meters .. " m", x + bar + 3, y + size + 1, 0.18, SGL_HUD_GREY, 1)
    djui_hud_set_font(FONT_NORMAL)
end

hook_event(HOOK_UPDATE, update)
hook_event(HOOK_ON_HUD_RENDER, draw)
function sgl_minimap_chat_notice()
    sChatUntil = get_time() + 10
end
hook_event(HOOK_ON_CHAT_MESSAGE, sgl_minimap_chat_notice)
hook_chat_command("minimap", "[on|off] Show or hide your local map", function(message)
    local option = (message or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
    if option ~= "" and option ~= "on" and option ~= "off" then
        sgl_hud_toast("Use /minimap on or /minimap off", 3)
        return true
    end
    if option == "" then sEnabled = not sEnabled else sEnabled = option == "on" end
    mod_storage_save("sgl_minimap_visible", sEnabled and "1" or "0")
    sgl_hud_toast(sEnabled and "Minimap on" or "Minimap off", 2)
    return true
end)
